// Service worker for the Model Workshop Manager PWA.
//
// Runtime-caching only — no install-time precache list — because this
// worker is hand-written rather than generated by a build plugin, so it
// has no manifest of hashed /assets/* filenames to enumerate up front.
// Instead, the app shell (documents, assets, icons) is cached as it's
// requested. /api/* is left untouched: this is app-shell caching, not
// offline data access.
//
// CACHE_NAME is versioned so that editing this file also drops any
// previous cache on the next activate. Registering this file at the same
// /sw.js URL is also what replaces the PR #31 kill-switch worker on
// clients that still had it — the browser diffs the new byte content and
// installs this version in its place.
const CACHE_NAME = "workshop-shell-v1";

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only handle same-origin GETs for app content. API calls, cross-origin
  // requests (fonts), and non-GET requests go straight to the network.
  if (request.method !== "GET" || url.origin !== self.location.origin) {
    return;
  }
  if (url.pathname.startsWith("/api/")) {
    return;
  }

  event.respondWith(request.mode === "navigate" ? networkFirst(request) : cacheFirst(request));
});

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    const cache = await caches.open(CACHE_NAME);
    cache.put(request, response.clone());
    return response;
  } catch {
    return (await caches.match(request)) ?? (await caches.match("/")) ?? Response.error();
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) {
    return cached;
  }
  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(CACHE_NAME);
    cache.put(request, response.clone());
  }
  return response;
}
